import type { Grade } from './types';
const grade: Grade =
{id:'g8',n:8,title:'Literatura colombiana y funcionamiento de la lengua',desc:'Autores colombianos, el poema por dentro, la oración compuesta y los discursos de los medios.',units:[
{id:'g8u1',title:'Literatura colombiana',desc:'Autores y obras, el género lírico y las figuras literarias.',lessons:[
 {id:'g8u1l1',title:'Panorama de la literatura colombiana',time:50,std:'Determino en las obras literarias latinoamericanas elementos textuales que dan cuenta de sus características estéticas, históricas y sociológicas, cuando sea pertinente.',dba:'DBA 3 (8°): caracteriza la literatura de un momento de la historia a partir de sus principales autores, obras, temas y recursos de estilo.',
  body:['La literatura colombiana tiene más de cuatro siglos. Para ordenarla usamos <b>movimientos</b>: grupos de autores de una misma época que comparten temas y estilo. Vamos a recorrerlos como las salas de un museo, de la más antigua a la más reciente.',
   'En el siglo XIX, el <b>Romanticismo</b> puso en el centro los sentimientos y el paisaje. <b>Jorge Isaacs</b> publicó <i>María</i> (1867): un amor imposible en una hacienda del Valle del Cauca.',
   'Al mismo tiempo, el <b>costumbrismo</b> retrató las costumbres y el habla de los pueblos. <b>Tomás Carrasquilla</b> escribió <i>Frutos de mi tierra</i> (1896) en habla antioqueña. <b>Candelario Obeso</b>, de Mompox, escribió <i>Cantos populares de mi tierra</i> (1877) en el habla de los bogas del río Magdalena.',
   'A finales del siglo XIX llegó el <b>Modernismo</b>, que buscaba la música y la belleza del lenguaje. Su gran poeta fue <b>José Asunción Silva</b>, autor del <i>Nocturno</i> (1894).',
   'En 1924, <b>José Eustasio Rivera</b> publicó <i>La vorágine</i>, una <b>novela de la tierra</b>. La selva es casi un personaje que devora a las personas. La obra denuncia la esclavitud y la explotación de los caucheros en la Amazonía.',
   '<b>Gabriel García Márquez</b> creó el pueblo de Macondo en <i>Cien años de soledad</i> (1967), la gran obra del <b>realismo mágico</b>: lo extraordinario se cuenta con la misma naturalidad que lo cotidiano. En 1982 ganó el Premio Nobel de Literatura.',
   'Luego llegaron las <b>voces contemporáneas</b>. <b>Andrés Caicedo</b> retrató la Cali de los setenta en <i>¡Que viva la música!</i> (1977). <b>Álvaro Mutis</b> creó al marinero <b>Maqroll el Gaviero</b> (<i>La nieve del almirante</i>, 1986). <b>Laura Restrepo</b> escribió <i>Delirio</i> (2004), y <b>Piedad Bonnett</b> es una gran poeta actual.'],
  bites:[{ej:'Como en un museo: cada sala es una época, con sus autores y sus obras.',ojo:'Orden de las salas: Romanticismo y costumbrismo → Modernismo → novela de la tierra → realismo mágico → voces contemporáneas.',check:{q:'¿Qué es un movimiento literario?',o:['Un grupo de autores de una época con temas y estilo parecidos','Un libro muy largo','Un premio de literatura'],a:0,e:'Un movimiento reúne autores de una misma época que se parecen en lo que cuentan y en cómo lo cuentan.'}},
   {ej:'En María, los personajes lloran y sufren, y el paisaje del Valle parece sentir con ellos.',ojo:'Romanticismo = sentimiento. Si todo es emoción y naturaleza, piensa en Isaacs.'},
   {ej:'Es como escribir un mensaje tal como habla tu abuela: "¿Qué más, mijo? ¿Ya comió?".',check:{q:'¿Qué retrató el costumbrismo?',o:['Las costumbres y el habla de los pueblos','Un pueblo mágico inventado','La selva que devora a las personas'],a:0,e:'Carrasquilla y Obeso escribieron como hablaba la gente de su región.'}},
   {ej:'Lee en voz alta "Una noche, / una noche toda llena de perfumes…": suena casi como una canción.',ojo:'Modernismo no quiere decir "moderno de hoy": es un movimiento de finales del siglo XIX.',check:{q:'¿Qué buscaba el Modernismo?',o:['La música y la belleza del lenguaje','Contar noticias','Retratar el habla antioqueña'],a:0,e:'Silva cuidaba el ritmo y el sonido de cada verso.'}},
   {ej:'La novela termina con la frase "¡Los devoró la selva!".',check:{q:'¿Qué denuncia La vorágine?',o:['La explotación de los caucheros en la Amazonía','Un amor imposible en el Valle','La vida en Macondo'],a:0,e:'Rivera mostró la esclavitud en las caucherías: es una novela de denuncia.'}},
   {ej:'En Macondo llueven flores amarillas y nadie se sorprende.',ojo:'Realismo mágico: lo mágico se cuenta como si fuera normal.'},
   {ojo:'En el tiempo: ¡Que viva la música! (1977), La nieve del almirante (1986) y Delirio (2004).',check:{q:'¿Qué personaje creó Álvaro Mutis?',o:['Maqroll el Gaviero','Juan Valdez','María'],a:0,e:'Maqroll el Gaviero es el marinero de las novelas de Mutis.'}}],
  key:'Romanticismo (Isaacs), costumbrismo (Carrasquilla, Obeso), Modernismo (Silva), novela de la tierra (Rivera), realismo mágico (García Márquez) y voces contemporáneas (Caicedo, Mutis, Restrepo, Bonnett).',
  co:'La Casa de Poesía Silva, en La Candelaria (Bogotá), funciona en la casa donde murió José Asunción Silva en 1896; hoy tiene lecturas, talleres y un archivo de voces de poetas.',
  act:{type:'map',kind:'timeline',prompt:'Pon cada obra en su año. Sobran dos tarjetas: no son de autores colombianos.',slots:[{label:'1867',a:'María · Jorge Isaacs'},{label:'1894',a:'Nocturno · José Asunción Silva'},{label:'1896',a:'Frutos de mi tierra · Tomás Carrasquilla'},{label:'1924',a:'La vorágine · José Eustasio Rivera'},{label:'1967',a:'Cien años de soledad · Gabriel García Márquez'},{label:'1986',a:'La nieve del almirante · Álvaro Mutis'},{label:'2004',a:'Delirio · Laura Restrepo'}],extra:['Pedro Páramo · Juan Rulfo (México)','Rayuela · Julio Cortázar (Argentina)'],e:'La línea va del Romanticismo y el costumbrismo al Modernismo, la novela de la tierra, el realismo mágico y las voces contemporáneas.'},
  quiz:[{q:'¿Quién escribió La vorágine?',o:['Jorge Isaacs','José Eustasio Rivera','Tomás Carrasquilla','Álvaro Mutis'],a:1,e:'José Eustasio Rivera, huilense, la publicó en 1924.',lv:'L'},
   {q:'María cuenta un amor imposible, con paisajes del Valle descritos con emoción y personajes que lloran y sufren. ¿A qué movimiento pertenece?',o:['Modernismo','Realismo mágico','Romanticismo','Novela de la tierra'],a:2,e:'El predominio del sentimiento y de la naturaleza como reflejo del ánimo son rasgos románticos.',lv:'I'},
   {q:'La vorágine termina con la frase "¡Los devoró la selva!". ¿Por qué se dice que es una novela de denuncia?',o:['Porque critica a los poetas modernistas','Porque muestra la esclavitud de los caucheros y la violencia de la selva sobre las personas','Porque cuenta la historia de Macondo','Porque es una novela de amor sin conflicto'],a:1,e:'Rivera mostró la explotación en las caucherías; su novela fue también una denuncia social.',lv:'C'}],
  tip:'Arme con el curso una línea del tiempo en el piso del salón: cada grupo representa una obra con un objeto y una frase.'},
 {id:'g8u1l2',title:'El poema: verso, estrofa y rima',time:55,std:'Identifico los recursos del lenguaje empleados por autores latinoamericanos de diferentes épocas y los comparo con los empleados por autores de otros contextos temporales y espaciales, cuando sea pertinente.',dba:'DBA 4 (8°): comprende que el género lírico se construye con musicalidad, rima y figuras retóricas para recrear una idea, un sentimiento o una situación.',
  body:['Cada línea de un poema es un <b>verso</b>. Los versos se miden en <b>sílabas métricas</b>: las sílabas que suenan al leer en voz alta. No siempre son las mismas que cuentas en gramática.',
   'Primera regla: la <b>sinalefa</b>. Si una palabra termina en vocal y la siguiente empieza por vocal, las dos se unen en una sola sílaba. <i>Baja el río</i> se cuenta <i>ba-<b>jael</b>-rí-o</i>.',
   'Segunda regla: la <b>ley del acento final</b>. Si el verso termina en palabra <b>aguda</b>, se suma una sílaba; si termina en <b>grave</b>, queda igual; si termina en <b>esdrújula</b>, se resta una. <i>Lan-za-su-red-al-jun-cal</i>: 7 + 1 = 8.',
   'Según su medida, el verso tiene nombre: <b>heptasílabo</b> (7 sílabas), <b>octosílabo</b> (8), <b>endecasílabo</b> (11) y <b>alejandrino</b> (14, en dos mitades de 7). Otros poetas miden con libertad: el <i>Nocturno</i> de Silva alarga y acorta sus versos y se sostiene en la repetición.',
   'Los versos se agrupan en <b>estrofas</b>. Con octosílabos se forman la <b>copla</b> y la <b>cuarteta</b>, de cuatro versos. El <b>soneto</b> tiene catorce endecasílabos: dos <b>cuartetos</b> y dos <b>tercetos</b>.',
   'La <b>rima</b> es la repetición de sonidos al final de los versos, desde la última vocal tónica. Es <b>consonante</b> si se repiten vocales y consonantes (<i>Magdal<b>ena</b> / p<b>ena</b></i>). Es <b>asonante</b> si solo se repiten las vocales (<i>c<b>a</b>s<b>a</b> / <b>a</b>lb<b>a</b></i>).',
   'La rima se anota con letras. En el esquema <b>abab</b>, el verso 1 rima con el 3, y el 2 con el 4. En el <b>romance</b> y en muchas coplas solo riman en asonante los versos pares; los impares quedan sueltos.'],
  bites:[{ej:'"Ba-ja-el-rí-o-Mag-da-le-na" tiene 9 sílabas en gramática, pero al leerlo en voz alta suena con 8.',check:{q:'¿Qué es un verso?',o:['Cada línea de un poema','Un grupo de estrofas','Una palabra que rima'],a:0,e:'El poema se escribe en líneas: cada una es un verso.'}},
   {ojo:'Truco: lee el verso dando palmas. Donde dos vocales se juntan entre palabras, das una sola palma.',check:{q:'¿Cómo se cuenta "sobre el" en un verso?',o:['Dos sílabas: so-breel','Tres sílabas: so-bre-el'],a:0,e:'La e final de "sobre" y la e de "el" se unen por sinalefa.'}},
   {ej:'"Una garza se levanta" termina en grave (le-VAN-ta): se queda en 8 sílabas.',check:{q:'Si el verso termina en palabra aguda…',o:['Se suma una sílaba','Se resta una sílaba','Queda igual'],a:0,e:'Aguda +1, grave igual, esdrújula −1.'}},
   {ojo:'Octo- es ocho, como en "octágono"; endeca- es once.',check:{q:'Un verso de 11 sílabas se llama…',o:['Endecasílabo','Octosílabo','Alejandrino'],a:0,e:'Endeca- significa once.'}},
   {ej:'Las coplas de las fiestas de pueblo suelen tener cuatro octosílabos.',ojo:'Soneto: 4 + 4 + 3 + 3 = 14 versos.',check:{q:'¿Cuántos versos tiene un soneto?',o:['14','8','4'],a:0,e:'Dos cuartetos y dos tercetos: 14 versos.'}},
   {ej:'"Café / José" riman en consonante (-é). "Luna / pluma" riman en asonante (u-a).',check:{q:'"Casa" y "alba" riman en…',o:['Asonante','Consonante'],a:0,e:'Solo coinciden las vocales a-a; las consonantes cambian.'}},
   {ej:'Baja el río Magdalena (a) / con su canto de metal (b) / y el pescador, con su pena (a) / lanza su red al juncal (b).',check:{q:'En el esquema abab, ¿con qué verso rima el primero?',o:['Con el tercero','Con el segundo','Con el cuarto'],a:0,e:'La misma letra marca la misma rima: 1 con 3.'}}],
  key:'Cuenta sílabas con sinalefa y ley del acento final (aguda +1, grave igual, esdrújula −1); nombra el verso por su medida; agrupa en estrofas; marca la rima con letras (consonante o asonante).',
  co:'El Nocturno de José Asunción Silva, publicado en 1894, es uno de los poemas más leídos y recitados del país: su ritmo acompaña a dos sombras que caminan juntas en una noche de luna.',
  act:{type:'mark',prompt:'Elige "Rima a", "b", "c" o "d" y toca la última palabra de cada verso. Con "Sinalefa", toca las palabras que se unen en una sílaba.',cats:[{n:'Rima a',c:'#1F5FA8'},{n:'Rima b',c:'#C0453A'},{n:'Rima c',c:'#2F7D32'},{n:'Rima d',c:'#8A4B6E'},{n:'Sinalefa',c:'#B06A10'}],text:'[[Baja el|4]] río [[Magdalena|0]] / con su canto de [[metal|1]]; / [[y el|4]] pescador, con su [[pena|0]], / lanza su red al [[juncal|1]]. — Una garza se [[levanta|2]] / [[sobre el|4]] agua del [[manglar|3]], / [[y el|4]] viento del sur le [[canta|2]] / una canción [[de alta|4]] [[mar|3]].',e:'Todos son octosílabos y el esquema es abab cdcd, con rima consonante.'},
  quiz:[{q:'¿Qué es la sinalefa?',o:['La repetición de una palabra al inicio del verso','La unión en una sílaba de la vocal final de una palabra y la inicial de la siguiente','Una estrofa de cuatro versos','La rima de solo vocales'],a:1,e:'Por la sinalefa, "baja el" se cuenta como "ba-jael".',lv:'L'},
   {q:'¿Cuántas sílabas métricas tiene "sobre el agua del manglar"?',o:['7','8','9','6'],a:1,e:'So-breel-a-gua-del-man-glar son 7; como termina en aguda se suma una: 8.',lv:'I'},
   {q:'El Nocturno de Silva no tiene versos de igual medida. ¿Qué le da entonces su musicalidad?',o:['Nada: por eso no es poesía','La repetición de palabras y de un ritmo de pasos que va y vuelve','Que todos sus versos tienen once sílabas','Que no usa ninguna figura literaria'],a:1,e:'La música de un poema no depende solo de la medida: la repetición ("una noche, una noche") y el ritmo también la crean.',lv:'C'}],
  tip:'Pida que cuenten sílabas con palmas y que se pongan de pie en cada sinalefa; luego lea en voz alta un fragmento del Nocturno para comparar.'},
 {id:'g8u1l3',title:'Figuras literarias',time:50,std:'Identifico los recursos del lenguaje empleados por autores latinoamericanos de diferentes épocas y los comparo con los empleados por autores de otros contextos temporales y espaciales, cuando sea pertinente.',dba:'DBA 4 (8°): comprende que el género lírico se construye con musicalidad, rima y figuras retóricas para recrear una idea, un sentimiento o una situación.',
  body:['Las <b>figuras literarias</b> usan las palabras de un modo distinto al de todos los días. Sirven para crear imágenes y para que el lector sienta lo que dice el texto.',
   'La <b>metáfora</b> dice que una cosa ES otra, sin usar "como": <i>tus ojos son luceros</i>. Los ojos se vuelven luceros porque brillan.',
   'El <b>símil</b> o comparación sí usa un enlace: <i>como</i>, <i>cual</i> o <i>parece</i>. Por ejemplo: <i>tu risa es como el agua de la quebrada</i>.',
   'La <b>hipérbole</b> exagera para dar fuerza a un sentimiento: <i>lloré tanto que se desbordó el Magdalena</i>, <i>te esperé mil años</i>.',
   'La <b>personificación</b> da rasgos humanos a animales, objetos o ideas: <i>la guitarra suspira cuando la abrazo</i>, <i>el viento susurra</i>.',
   'La <b>anáfora</b> repite una palabra al inicio de varios versos o frases: <i>por ti canto, por ti sueño, por ti vivo</i>. El bambuco y el vallenato están llenos de figuras: son <b>poesía cantada</b>.',
   'Hay más figuras. La <b>antítesis</b> enfrenta ideas contrarias: <i>es hielo abrasador, es fuego helado</i>. La <b>onomatopeya</b> imita un sonido: <i>el tic tac del reloj</i>. El <b>epíteto</b> es un adjetivo que destaca algo que el sustantivo ya tiene: <i>la blanca nieve</i>.'],
  bites:[{ej:'"Estoy triste" informa. "Tengo el corazón hecho pedazos" te hace ver y sentir la tristeza.',check:{q:'¿Para qué sirven las figuras literarias?',o:['Para crear imágenes y emociones','Para dar datos exactos','Para acortar el texto'],a:0,e:'Convierten lo que se siente en imágenes que el lector puede imaginar.'}},
   {ej:'"Mi corazón es un acordeón que suena por ti."',ojo:'Metáfora: A es B. Si aparece "como", ya no es metáfora.'},
   {ej:'"Tu voz, suave como un bambuco de la tarde."',check:{q:'"Blanca como la nieve" es…',o:['Símil','Metáfora'],a:0,e:'Usa el enlace "como": es un símil.'}},
   {ej:'"Te lo he dicho un millón de veces."',check:{q:'"Tengo tanta hambre que me comería una vaca" es…',o:['Hipérbole','Anáfora','Símil'],a:0,e:'Nadie se come una vaca: es una exageración.'}},
   {ej:'"El río canta de noche y llora en verano."',ojo:'Pregúntate: ¿esa acción la hace una persona? Si la hace una cosa o un animal, es personificación.',check:{q:'"La luna nos espía" es…',o:['Personificación','Hipérbole'],a:0,e:'Espiar es una acción humana que se le da a la luna.'}},
   {ej:'"Cada tarde te recuerdo, cada tarde te nombro, cada tarde te pierdo."',ojo:'En la anáfora la repetición va AL INICIO de cada verso o frase.'},
   {ej:'"El verde prado": todo prado es verde; el adjetivo solo lo destaca.',check:{q:'"El guau del perro" es…',o:['Onomatopeya','Epíteto','Antítesis'],a:0,e:'"Guau" imita el ladrido: es onomatopeya.'}}],
  key:'Metáfora: A es B. Símil: A como B. Hipérbole: exagera. Personificación: humaniza. Anáfora: repite al inicio. Antítesis: opone. Onomatopeya: imita sonidos. Epíteto: adjetivo que ya está en el sustantivo.',
  co:'Los vallenatos de Rafael Escalona y los bambucos que se cantan en el Festival Mono Núñez, en Ginebra (Valle), cuentan historias con metáforas, hipérboles y personificaciones: son poesía que se baila y se canta.',
  act:{type:'classify',prompt:'¿Qué figura hay en cada verso? Ponlo en su caja.',bins:['Metáfora','Símil','Hipérbole','Personificación','Anáfora'],items:[['Tus ojos son dos luceros que alumbran mi camino',0],['Tu risa es como el agua de la quebrada',1],['Te esperé mil años en la esquina del parque',2],['El río canta de noche y llora en verano',3],['Por ti canto, por ti sueño, por ti vivo',4],['Mi corazón es un acordeón que suena por ti',0],['Tu voz, suave como un bambuco de la tarde',1],['Lloré tanto que se desbordó el Magdalena',2],['La guitarra suspira cuando la abrazo',3],['Cada tarde te recuerdo, cada tarde te nombro, cada tarde te pierdo',4]],e:'Si hay "como", "cual" o "parece", es símil; si A se vuelve B sin enlace, es metáfora.'},
  quiz:[{q:'¿Qué figura hay en "La luna es un farol de plata"?',o:['Símil','Metáfora','Anáfora','Hipérbole'],a:1,e:'La luna se identifica con un farol sin usar "como".',lv:'L'},
   {q:'"El viento se llevó mis penas y se rio de mí." ¿Por qué es una personificación?',o:['Porque exagera','Porque el viento hace acciones humanas, como reírse','Porque compara con "como"','Porque repite una palabra'],a:1,e:'Reírse es propio de las personas: se le atribuye al viento.',lv:'I'},
   {q:'Un vallenato dice que el cantante "tiene el corazón hecho pedazos". ¿Qué logra esa imagen frente a decir "estoy triste"?',o:['Nada, dice lo mismo','Informa un dato médico','Hace el texto más corto','Hace visible y más intensa la tristeza con una imagen concreta'],a:3,e:'La figura convierte un sentimiento abstracto en una imagen que el oyente puede sentir.',lv:'C'}],
  tip:'Lleve la letra de un bambuco o un vallenato tradicional y pida a los grupos que subrayen cada figura con un color distinto.'}
]},
{id:'g8u2',title:'La oración compuesta',desc:'Coordinación y subordinación, coherencia, cohesión y concordancia.',lessons:[
 {id:'g8u2l1',title:'Oraciones coordinadas y subordinadas',time:55,std:'Produzco textos escritos que evidencian el conocimiento que he alcanzado acerca del funcionamiento de la lengua en situaciones de comunicación y el uso de las estrategias de producción textual.',dba:'DBA 8 (8°): produce textos escritos teniendo en cuenta el funcionamiento de la lengua, el propósito y el público al que se dirige.',
  body:['Una <b>oración simple</b> tiene un solo verbo conjugado: <i>Rock al Parque <b>es</b> gratis</i>. Una <b>oración compuesta</b> tiene dos o más verbos conjugados. Cada parte con su verbo se llama <b>proposición</b>.',
   'Las proposiciones se unen con un <b>nexo</b>: <i>Rock al Parque es gratis <b>y</b> reúne a miles de jóvenes</i>. Hay dos maneras de unirlas: <b>coordinar</b> o <b>subordinar</b>.',
   'En las <b>coordinadas</b>, las proposiciones están al mismo nivel: cada una podría ir sola. <i>La banda tocó</i> + <i>el público aplaudió</i> = <i>La banda tocó <b>y</b> el público aplaudió</i>.',
   'Los nexos coordinantes son de tres clases. <b>Copulativos</b>, que suman: <i>y, e</i>, y <i>ni</i> para sumar negaciones. <b>Disyuntivos</b>, que dan a elegir: <i>o, u</i>. <b>Adversativos</b>, que marcan un contraste: <i>pero, mas, sino que</i>.',
   'En las <b>subordinadas</b>, una proposición depende de otra, la <b>principal</b>, y no se entiende sola. <i>Porque queríamos ver a la primera banda</i>, así suelta, deja la idea incompleta.',
   'Cada nexo subordinante dice qué aporta la subordinada: <i>porque</i>, la <b>causa</b>; <i>si</i>, la <b>condición</b>; <i>cuando</i>, el <b>tiempo</b>; <i>donde</i>, el <b>lugar</b>.',
   'El nexo <i>que</i> tiene dos usos. Después de verbos como <i>decir</i> o <i>anunciar</i> forma una <b>subordinada sustantiva</b>, que dice lo que se dice: <i>Me dijo <b>que</b> vendría</i>. Después de un sustantivo, lo describe: <i>El grupo <b>que</b> tocó primero es de Cali</i>.'],
  bites:[{ej:'"Llegué tarde" es simple (un verbo). "Llegué tarde y me regañaron" es compuesta (llegué, regañaron).',check:{q:'¿Cuántos verbos conjugados tiene una oración simple?',o:['Uno','Dos o más'],a:0,e:'Simple: un verbo. Compuesta: dos o más.'}},
   {ojo:'Truco: cuenta los verbos conjugados. Tantos verbos, tantas proposiciones.',ej:'"Salimos temprano porque el metro cierra a las once": dos verbos (salimos, cierra), un nexo (porque).'},
   {ej:'"Unos cantaban y otros bailaban." "Unos cantaban" funciona solo; "otros bailaban", también.',check:{q:'En una oración coordinada, cada proposición…',o:['Podría ir sola','Depende de la otra'],a:0,e:'Las coordinadas están al mismo nivel.'}},
   {ej:'"No llamó ni escribió" (suma negaciones). "¿Vienes o te quedas?" (elegir). "Llovió, pero nadie se fue" (contraste).',ojo:'"Y" cambia a "e" antes de i: "Juan e Isabel". "O" cambia a "u" antes de o: "siete u ocho".',check:{q:'"Pero" es un nexo…',o:['Adversativo','Copulativo','Disyuntivo'],a:0,e:'"Pero" marca un contraste: es adversativo.'}},
   {ej:'"Cuando empezó la música…" ¿Qué pasó? Falta la principal: "todos saltaron".',check:{q:'En una oración subordinada, una proposición…',o:['Depende de la principal','Va al mismo nivel que la otra'],a:0,e:'La subordinada necesita a la principal para tener sentido.'}},
   {ej:'"Si llueve, llevamos capa" (condición). "Iremos donde tú quieras" (lugar).',check:{q:'En "No fui porque estaba enfermo", "porque" expresa…',o:['La causa','El tiempo','El lugar'],a:0,e:'"Porque" explica por qué pasó algo.'}},
   {ej:'"La organización anunció que la entrada será gratuita." ¿Qué anunció? Que la entrada será gratuita.',ojo:'Pregunta "¿qué dijo?" o "¿qué anunció?": si la respuesta es la subordinada, es sustantiva.',check:{q:'En "El grupo que tocó primero es de Cali", la subordinada…',o:['Describe al grupo','Dice la causa'],a:0,e:'Va después del sustantivo "grupo" y lo describe.'}}],
  key:'Coordinadas: dos proposiciones al mismo nivel (y, ni: suma; o: elección; pero: contraste). Subordinadas: una depende de la otra (porque: causa; si: condición; cuando: tiempo; donde: lugar; que: lo que se dice o describe un sustantivo).',
  co:'Rock al Parque, en el parque Simón Bolívar de Bogotá, es uno de los festivales gratuitos de rock más grandes de América Latina: se hace desde 1995.',
  act:{type:'build',prompt:'Toca las piezas para unir las dos oraciones con el nexo que se pide.',rounds:[{q:'Nexo copulativo (suma ideas)',pieces:['El festival es gratis','y','pero','llegan bandas de todo el mundo'],answers:[['El festival es gratis','y','llegan bandas de todo el mundo']],slots:['Proposición 1','Nexo','Proposición 2'],hint:'El nexo copulativo más común es "y".'},{q:'Nexo adversativo (contraste)',pieces:['Llovió toda la tarde','pero','o','el público no se fue del parque'],answers:[['Llovió toda la tarde','pero','el público no se fue del parque']],slots:['Proposición 1','Nexo','Proposición 2'],hint:'Busca el nexo que opone dos ideas.'},{q:'Nexo disyuntivo (elegir)',pieces:['¿Vamos el sábado','o','porque','preferimos ir el domingo?'],answers:[['¿Vamos el sábado','o','preferimos ir el domingo?']],slots:['Proposición 1','Nexo','Proposición 2'],hint:'Se ofrece elegir entre dos opciones.'},{q:'Subordinada de causa (explica por qué)',pieces:['Llegamos temprano','porque','ni','queríamos ver a la primera banda'],answers:[['Llegamos temprano','porque','queríamos ver a la primera banda']],slots:['Principal','Nexo','Subordinada'],hint:'La segunda parte dice la causa.'},{q:'Subordinada de condición',pieces:['Iremos al concierto','si','ni','no llueve'],answers:[['Iremos al concierto','si','no llueve']],slots:['Principal','Nexo','Subordinada'],hint:'La condición se introduce con "si".'},{q:'Subordinada sustantiva (lo que se anuncia)',pieces:['La organización anunció','que','o','la entrada será gratuita'],answers:[['La organización anunció','que','la entrada será gratuita']],slots:['Principal','Nexo','Subordinada'],hint:'¿Qué anunció? Eso es la subordinada.'}],e:'En las coordinadas cada proposición podría ir sola; en las subordinadas, la segunda depende de la principal.'},
  quiz:[{q:'¿Cuál es una oración compuesta?',o:['Los jóvenes bailan en el parque.','Los jóvenes bailan y los guardias vigilan.','El parque grande y verde.','Música en vivo todo el día.'],a:1,e:'Tiene dos verbos conjugados (bailan, vigilan) unidos por "y".',lv:'L'},
   {q:'En "Te presto el impermeable si me lo devuelves mañana", ¿qué relación expresa el nexo?',o:['Suma','Contraste','Condición','Elección'],a:2,e:'"Si" introduce la condición para que se cumpla la principal.',lv:'I'},
   {q:'Un estudiante escribe: "Llegué tarde. El bus se varó. Me regañaron." ¿Qué ganaría uniéndolas en oraciones compuestas?',o:['Nada, así está perfecto','Mostrar la relación entre las ideas: "Llegué tarde porque el bus se varó, y me regañaron"','Solo hacer el texto más largo','Cambiar el significado de los hechos'],a:1,e:'Los nexos muestran la causa y la suma de hechos; el lector no tiene que adivinarlas.',lv:'C'}],
  tip:'Escriba oraciones simples en tiras de papel y reparta nexos en tarjetas de colores: coordinantes de un color y subordinantes de otro.'},
 {id:'g8u2l2',title:'Coherencia y cohesión',time:50,std:'Comprendo e interpreto textos, teniendo en cuenta el funcionamiento de la lengua en situaciones de comunicación, el uso de estrategias de lectura y el papel del interlocutor y del contexto.',dba:'DBA 6 y 8 (8°): infiere sentidos de los textos a partir de su organización; produce textos con coherencia y cohesión.',
  body:['Un texto es <b>coherente</b> cuando todas sus ideas giran alrededor de un mismo <b>tema</b>. Si una oración habla de otra cosa, el lector se pierde.',
   'La coherencia también pide un <b>orden lógico</b>: las ideas avanzan paso a paso, sin saltos. Una crónica, por ejemplo, sigue el recorrido o el paso del tiempo.',
   'La <b>cohesión</b> son las piezas que unen las oraciones. Las más visibles son los <b>conectores</b>: <i>luego, además, sin embargo, por eso, finalmente</i>.',
   'Los <b>pronombres</b> remiten a algo ya dicho (<i>la, las, ella, allí</i>) y los <b>sinónimos</b> evitan repetir la misma palabra: <i>Vi a una señora con obleas; <b>ella</b> misma <b>las</b> rellenaba</i>.',
   'Cada conector dice una relación. <b>Suma</b>: <i>además, también</i>. <b>Contraste</b>: <i>sin embargo, aun así</i> (algo pasa a pesar de lo anterior) y <i>en cambio</i> (opone dos cosas). <b>Explicación</b>: <i>es decir, o sea</i> (lo mismo con otras palabras).',
   'Más relaciones. <b>Consecuencia</b>: <i>por eso, así que, por lo tanto, gracias a esto</i>. <b>Orden en el tiempo</b>: <i>primero, luego, después, por último, finalmente</i>.',
   'Sin coherencia ni cohesión, el texto se cae como un edificio sin columnas. Al revisar, pregúntate: ¿el orden tiene sentido?, ¿cada pronombre deja claro a quién se refiere?, ¿cada conector dice la relación correcta?'],
  bites:[{ej:'Una crónica sobre la Séptima que de pronto habla de las fases de la Luna pierde el tema.',check:{q:'Un texto coherente…',o:['Mantiene un mismo tema','Cambia de tema en cada oración'],a:0,e:'Todas las ideas giran alrededor del tema.'}},
   {ej:'Receta de arepas: primero mezclar, después amasar, luego formar bolitas y por último asar.',check:{q:'Si las ideas saltan de un lado a otro sin razón, falla…',o:['El orden lógico','La ortografía'],a:0,e:'La coherencia pide que las ideas avancen en orden.'}},
   {ojo:'Los conectores son como los tornillos de un mueble: sin ellos, las piezas quedan sueltas.',check:{q:'¿Cuál es un conector?',o:['Sin embargo','Obleas','Séptima'],a:0,e:'"Sin embargo" une dos ideas y marca un contraste.'}},
   {ej:'"Fui a la plaza de Bolívar. Allí vi a un mimo." "Allí" = la plaza.',ojo:'Si un pronombre puede referirse a dos cosas, el lector se confunde: mejor repite el nombre o usa un sinónimo.',check:{q:'En "compré obleas y las compartí", "las" se refiere a…',o:['Las obleas','Las personas'],a:0,e:'El pronombre retoma "obleas" para no repetirla.'}},
   {ej:'"La arepa boyacense es dulce; en cambio, la antioqueña casi no tiene sal."',check:{q:'"Llovió; aun así, el concierto empezó a tiempo" expresa…',o:['Contraste','Suma','Explicación'],a:0,e:'El concierto empezó a pesar de la lluvia.'}},
   {ej:'"El bus iba lleno, así que decidimos caminar."',check:{q:'"Por eso" expresa…',o:['Consecuencia','Tiempo'],a:0,e:'Presenta lo que resulta de lo anterior.'}},
   {ojo:'Lee tu texto en voz alta: donde tropiezas, casi siempre falta un conector o hay un salto.'}],
  key:'Coherencia: un tema y un orden lógico. Cohesión: conectores, pronombres y sinónimos que unen las oraciones. Cada conector dice una relación: suma, contraste, consecuencia, tiempo o explicación.',
  co:'La carrera Séptima, entre la plaza de Bolívar y la calle 26, es peatonal: allí conviven artistas callejeros, vendedores y oficinistas. Es un escenario perfecto para una crónica.',
  act:{type:'order',prompt:'Esta crónica de la Séptima quedó desarmada. Ordénala: fíjate en los conectores y pronombres.',items:['El sábado empecé mi recorrido por la Séptima peatonal en la plaza de Bolívar.','Allí, frente a la Catedral, un grupo de niños rodeaba a un mimo que imitaba a los transeúntes.','Luego caminé hacia el norte y, a la altura de la avenida Jiménez, escuché un arpa llanera.','Unos metros más adelante, una señora vendía obleas; ella misma las rellenaba con arequipe frente a los clientes.','Sin embargo, no todo era fiesta: varios vendedores se quejaban de que ese día habían vendido poco.','Finalmente, al llegar a la calle 26, entendí que la Séptima es al mismo tiempo escenario, mercado y lugar de paso.'],e:'"Allí", "luego" y "finalmente" marcan el recorrido; "sin embargo" trae el contraste; "ella" y "las" remiten a la señora y a las obleas.'},
  quiz:[{q:'¿Cuál de estas palabras es un conector?',o:['Obleas','Séptima','Mimo','Sin embargo'],a:3,e:'"Sin embargo" une dos ideas e indica contraste.',lv:'L'},
   {q:'En "Vi a una señora con obleas; ella misma las rellenaba", ¿a qué se refiere "las"?',o:['A la señora','A las obleas','A los clientes','A la Séptima'],a:1,e:'El pronombre "las" retoma el sustantivo "obleas" para no repetirlo.',lv:'I'},
   {q:'Un texto dice: "Los perros necesitan paseos diarios. Por eso, la Luna tiene cuatro fases." ¿Qué falla?',o:['La ortografía','La coherencia: el conector anuncia una consecuencia que no tiene relación con lo anterior','La concordancia','Nada, está bien escrito'],a:1,e:'Las oraciones están bien formadas, pero no hablan del mismo tema y "por eso" une ideas sin relación.',lv:'C'}],
  tip:'Recorte una crónica corta en tiras, quite los conectores y rete a los grupos a reconstruirla y a justificar cada conector que agreguen.'},
 {id:'g8u2l3',title:'La concordancia',time:50,std:'Tengo en cuenta reglas sintácticas, semánticas y pragmáticas para la producción de un texto.',dba:'DBA 8 (8°): produce textos escritos teniendo en cuenta el funcionamiento de la lengua, el propósito y el público al que se dirige.',
  body:['La <b>concordancia</b> es el acuerdo entre palabras. El artículo y el adjetivo concuerdan con el sustantivo en <b>género</b> (masculino o femenino) y en <b>número</b> (singular o plural): <i>las calles empinadas de Manizales</i>.',
   'El verbo concuerda con el <b>sujeto</b> en <b>número</b> y <b>persona</b>: <i>Los estudiantes <b>llegaron</b></i>. Busca el sujeto aunque vaya después del verbo: <i><b>Faltan</b> tres días</i>.',
   'Si el sujeto incluye a <i>yo</i>, equivale a <i>nosotros</i>: <i>Mi primo y yo <b>fuimos</b></i>. Si incluye a <i>tú</i> o <i>usted</i> sin <i>yo</i>, equivale a <i>ustedes</i>: <i>Tú y ella <b>cantan</b></i>.',
   'Los sustantivos <b>colectivos</b> nombran un grupo, pero son singulares: <i>La gente <b>llegó</b></i>, <i>El equipo <b>ganó</b></i>.',
   'En avisos hay errores comunes. <i>Se <b>venden</b> empanadas</i>: el verbo concuerda con "empanadas". Y el verbo <b>haber</b> que indica existencia va siempre en singular: <i><b>Hubo</b> problemas</i>, <i><b>Había</b> personas</i>, <i><b>Debe</b> haber soluciones</i>.',
   'El género no siempre se ve en la terminación. <i>Agua</i>, <i>aula</i> y <i>águila</i> son femeninas aunque lleven "el", porque empiezan por <i>a</i> tónica: <i>el agua <b>fría</b></i>, <i>el aula <b>limpia</b></i>.',
   '<i>Mano</i> es femenino aunque termine en -o: <i><b>esta</b> mano</i>. <i>Mapa</i>, <i>tema</i> y <i>problema</i> son masculinos aunque terminen en -a: <i>el mapa <b>antiguo</b></i>.'],
  bites:[{ej:'"Las montañas verdes" está bien. "Las montañas verde" está mal.',check:{q:'¿Cuál concuerda?',o:['Las casas blancas','Las casa blancas'],a:0,e:'Artículo, sustantivo y adjetivo en femenino plural.'}},
   {ojo:'Pregúntale al verbo "¿quién?" o "¿qué?": ¿qué falta? Tres días. Entonces: faltan.',check:{q:'"___ tres días para el festival."',o:['Faltan','Falta'],a:0,e:'El sujeto es "tres días", plural.'}},
   {ej:'"Usted y yo somos vecinos." "Tú y ella cantan vallenatos."',check:{q:'"Mi mamá y yo ___ al mercado."',o:['vamos','van'],a:0,e:'"Mi mamá y yo" equivale a "nosotras": vamos.'}},
   {ojo:'Colectivos comunes: gente, equipo, familia, público, grupo. Todos van en singular.',check:{q:'"La gente ___ temprano."',o:['llegó','llegaron'],a:0,e:'"Gente" es singular.'}},
   {ej:'Aviso de tienda: "Se arreglan celulares" está bien; "Se arregla celulares", mal.',ojo:'"Hubieron", "habían muchas personas" y "deben haber" son errores: ese "haber" no tiene plural.',check:{q:'¿Cuál está bien escrita?',o:['Hubo muchos accidentes','Hubieron muchos accidentes'],a:0,e:'"Haber" de existencia va en singular.'}},
   {ej:'"El aula limpia huele a pino." "El águila está herida."',check:{q:'¿Cuál está bien escrita?',o:['El agua fría','El agua frío'],a:0,e:'"Agua" es femenina: el adjetivo va en femenino.'}},
   {ej:'"El tema principal es la paz." "Esta mano está herida."',check:{q:'¿Cuál está bien escrita?',o:['El problema grave','La problema grave'],a:0,e:'"Problema" es masculino aunque termine en -a.'}}],
  key:'Sustantivo, artículo y adjetivo: mismo género y número. Sujeto y verbo: mismo número y persona (yo + otro = nosotros; tú + otro = ustedes). "Hubo", "había", "debe haber": siempre en singular.',
  co:'En las calles colombianas abundan avisos como "Se vende arepas" o "Hubieron cambios en el horario": son buenos ejercicios para practicar la concordancia.',
  act:{type:'fix',prompt:'Toca cada palabra que no concuerda y elige el arreglo.',text:'En la tienda de doña Marleny {{se venden|se vende}} empanadas, arepas y jugos. Ayer {{hubo|hubieron}} tantos clientes que el agua {{fría|frío}} se acabó al mediodía. La gente {{llegó|llegaron}} desde temprano porque las empanadas estaban recién hechas. Mi primo y yo {{ayudamos|ayudaron}} a atender, y al final los clientes {{quedaron|quedó}} contentos.',e:'Busca siempre el sujeto: "empanadas" es plural, "la gente" es singular y "mi primo y yo" equivale a "nosotros".'},
  quiz:[{q:'¿Cuál oración tiene buena concordancia?',o:['Las casa blancas','Los niños juega fútbol','Las montañas verdes rodean el pueblo','El agua frío'],a:2,e:'Artículo, sustantivo y adjetivo están en femenino plural, y el verbo concuerda con "montañas".',lv:'L'},
   {q:'Un letrero dice "Hubieron muchos accidentes en esta curva". ¿Cómo se corrige?',o:['Hubieron muchos accidente','Hubo muchos accidentes','Habían muchos accidentes','Está bien escrito'],a:1,e:'"Haber" de existencia es impersonal: va en singular.',lv:'I'},
   {q:'¿Por qué importa la concordancia en un aviso público?',o:['No importa, igual se entiende','Porque los errores distraen y restan credibilidad al mensaje','Porque así lo exige la ley','Porque los avisos solo los leen profesores'],a:1,e:'Un aviso con errores parece descuidado; escribir bien es parte de comunicar con claridad y respeto.',lv:'C'}],
  tip:'Pida a los estudiantes que fotografíen avisos de su barrio con errores de concordancia y los corrijan en una cartelera sin burlarse de nadie.'}
]},
{id:'g8u3',title:'Discursos y culturas',desc:'Noticia, opinión y publicidad; escuchar y dialogar; arte y comunidad.',lessons:[
 {id:'g8u3l1',title:'Noticia, opinión y publicidad',time:50,std:'Retomo crítica y selectivamente la información que circula a través de los medios de comunicación masiva, para confrontarla con la que proviene de otras fuentes.',dba:'DBA 1 (8°): utiliza la información de los medios teniendo en cuenta el mensaje, los interlocutores, la intención y el contexto de producción.',
  body:['Los medios producen textos con intenciones distintas. Unos <b>informan</b>, otros <b>opinan</b> y otros buscan <b>vender</b>. Para leerlos bien, pregúntate siempre: ¿quién habla y qué quiere de mí?',
   'La <b>noticia</b> y el <b>reportaje</b> informan. Cuentan hechos que se pueden comprobar, en tercera persona y con <b>fuentes</b>: quién dio cada dato.',
   'La <b>opinión</b> valora ("creo que", "es inaceptable") y da <b>argumentos</b>. Siempre va firmada o marcada como opinión. La <b>columna</b> es la opinión de quien la firma; el <b>editorial</b>, la del propio periódico, y la <b>caricatura</b> opina con humor y dibujos.',
   'La <b>publicidad</b> persuade con <b>eslóganes</b>, imágenes y emociones. Muchas marcas apelan al orgullo regional, a la finca o al "sabor de la abuela". No siempre mienten, pero eligen qué mostrar para <b>vender</b>.',
   'Antes de creer o compartir, revisa la <b>fuente</b>, la fecha y si otros medios dicen lo mismo. Una información es <b>confiable</b> si cita fuentes identificables, da datos comprobables y coincide con otros medios u organismos oficiales.',
   'Es <b>engañosa</b> si parte de un hecho real, pero lo exagera, lo generaliza a partir de pocos casos o usa una foto vieja fuera de contexto.',
   'Es <b>falsa</b> si el hecho no ocurrió. Pistas: no tiene fuentes, promete algo imposible, contradice a las autoridades o es una broma de una página de humor que circula como noticia.'],
  bites:[{ej:'En un mismo día ves una noticia sobre el metro, una columna que lo critica y un anuncio de tenis.',check:{q:'¿Qué pregunta te ayuda a leer los medios?',o:['¿Quién habla y qué quiere de mí?','¿Cuántas páginas tiene?'],a:0,e:'Descubrir la intención te deja leer con criterio.'}},
   {ej:'"El Ideam informó que el nivel del río Magdalena bajó esta semana." La fuente es el Ideam.',check:{q:'¿Qué necesita una noticia?',o:['Hechos comprobables y fuentes','La opinión del periodista'],a:0,e:'La noticia informa hechos y dice de dónde salen.'}},
   {ej:'"En mi opinión, el colegio necesita más zonas verdes."',ojo:'Editorial = la voz del periódico. Columna = la voz de una persona con nombre.',check:{q:'¿Qué texto expresa la posición del propio periódico?',o:['El editorial','La columna','La noticia'],a:0,e:'El editorial habla por el medio, no por un periodista.'}},
   {ej:'Juan Valdez es un personaje publicitario creado para vender café colombiano, no una persona real.',ojo:'Publicidad disfrazada: parece noticia, pero al final te pide comprar algo.'},
   {ej:'Una emisora enlaza el boletín oficial y otros medios dicen lo mismo: es confiable.',check:{q:'¿Qué haces antes de compartir una noticia?',o:['Reviso la fuente, la fecha y otros medios','La comparto rápido para ser el primero'],a:0,e:'Contrastar evita que ayudes a regar mentiras.'}},
   {ej:'Una "encuesta" a 20 personas de un barrio se presenta como "el 90 % de los jóvenes del país".',check:{q:'Una foto de 2019 usada en una noticia de hoy hace que la información sea…',o:['Engañosa','Confiable'],a:0,e:'La foto es real, pero está fuera de contexto.'}},
   {ej:'"¡Tomar agua de panela con limón cura el dengue!", en una cadena sin autor.',ojo:'Si un mensaje te pide reenviarlo a diez contactos, desconfía.',check:{q:'Una broma de una página de humor que circula como noticia es…',o:['Falsa','Confiable'],a:0,e:'El hecho nunca ocurrió.'}}],
  key:'Informar: hechos y fuentes. Opinar: valoraciones y argumentos firmados. Vender: persuadir con emociones y eslóganes. Antes de compartir: ¿confiable, engañosa o falsa?',
  co:'Juan Valdez, el caficultor con su mula Conchita, fue creado a finales de los años cincuenta por la Federación Nacional de Cafeteros para promocionar el café de Colombia en el mundo: es un personaje publicitario, no una persona real.',
  act:{type:'choose',prompt:'Lee cada caso y elige la respuesta.',items:[
   {s:'"El Ideam informó que el nivel del río Magdalena bajó esta semana."',o:['Informa','Opina','Vende'],a:0,e:'Da un hecho y dice la fuente: informa.'},
   {s:'Columna: "El reguetón no es enemigo de la cultura; es parte de ella."',o:['Informa','Opina','Vende'],a:1,e:'Es una valoración firmada en una columna: opina.'},
   {s:'"Bocadillo veleño: la dulzura que viene de Santander."',o:['Informa','Opina','Vende'],a:2,e:'Es un eslogan que apela al orgullo regional: vende.'},
   {s:'Editorial: "La ciudad no puede seguir aplazando el metro."',o:['Informa','Opina','Vende'],a:1,e:'El editorial es la opinión del propio periódico.'},
   {s:'Un video parece noticia, pero al final dice: "Compre ya la crema milagrosa".',o:['Informa','Opina','Vende'],a:2,e:'Es publicidad disfrazada de noticia.'},
   {s:'Una nota cita a la Secretaría de Salud, da cifras que se pueden comprobar y otros medios dicen lo mismo.',o:['Confiable','Engañosa','Falsa'],a:0,e:'Fuentes, datos comprobables y coincidencia: es confiable.'},
   {s:'Una cuenta publica "Así quedó el estadio anoche" con una foto de 2019.',o:['Confiable','Engañosa','Falsa'],a:1,e:'Puede que el partido sí existiera, pero la foto vieja está fuera de contexto: es engañosa.'},
   {s:'Un audio sin autor asegura que comer mango verde con sal borra los recuerdos.',o:['Confiable','Engañosa','Falsa'],a:2,e:'No tiene fuente y promete algo imposible: es falsa.'}],e:'Primero pregúntate qué quiere el texto; luego, si puedes confiar en él.'},
  quiz:[{q:'¿Qué texto periodístico expresa la posición de un periódico sobre un tema?',o:['La noticia','El editorial','El titular','La fe de erratas'],a:1,e:'El editorial es la opinión del medio, no de un periodista en particular.',lv:'L'},
   {q:'Un anuncio muestra a una abuela sonriente amasando arepas y dice: "Como las de antes". ¿Qué busca?',o:['Informar cómo se hacen arepas','Despertar nostalgia y confianza para que compres','Opinar sobre la cocina antigua','Criticar la comida moderna'],a:1,e:'La publicidad apela a emociones (la familia, la tradición) para persuadir.',lv:'I'},
   {q:'Un video en redes parece noticia, pero al final recomienda comprar un producto. ¿Qué deberías hacer?',o:['Creerle todo porque parece noticia','Compartirlo de inmediato','Ignorar todas las noticias','Reconocer que es publicidad disfrazada y buscar la información en otras fuentes'],a:3,e:'Identificar la intención real del texto permite leerlo con criterio y contrastarlo.',lv:'C'}],
  tip:'Lleve un periódico del día y pida a cada grupo que recorte una noticia, una columna y un aviso, y que subraye las pistas de su intención.'},
 {id:'g8u3l2',title:'Escuchar y dialogar',time:50,std:'Identifico en situaciones comunicativas reales los roles, las intenciones de los interlocutores y el respeto por los principios básicos de la comunicación.',dba:'DBA 5 y 7 (8°): interpreta las intenciones de distintos textos, también orales; produce textos orales con estrategias para exponer sus ideas y responder al otro.',
  body:['<b>Oír</b> no es lo mismo que <b>escuchar</b>. Oír es percibir el sonido. Escuchar es poner atención para comprender lo que el otro dice.',
   'La <b>escucha activa</b> es prestar atención completa: mirar a quien habla, asentir con la cabeza, no interrumpir y hacer preguntas. Mirar el celular o ir pensando la respuesta mientras el otro habla no es escuchar.',
   '<b>Parafrasear</b> es decir con otras palabras lo que el otro dijo, para comprobar que entendimos: "O sea que usted dice que…". Primero se entiende; luego se responde.',
   'Detrás de cada frase hay una <b>intención</b>: <b>saludar</b>, <b>pedir</b>, <b>reclamar</b> por un problema, <b>ofrecer</b> un trato o una ayuda, <b>negociar</b> un acuerdo, <b>advertir</b> de un peligro, <b>disculparse</b> o <b>agradecer</b>.',
   'El <b>tono</b>, el volumen y las pausas ayudan a descubrir la intención. "¿Me regala una bolsa?" dicho con calma es una petición; dicho de mal genio puede ser un reclamo.',
   'Dialogar es respetar los <b>turnos</b>, usar fórmulas de <b>cortesía</b> (<i>buenos días, por favor, con gusto, sumercé</i>) y responder a lo que el otro realmente quiere.',
   'Se puede estar en desacuerdo y decirlo con respeto, sin burlas ni gritos: eso es ser <b>asertivo</b>. Por ejemplo: "Entiendo su punto, pero yo lo veo distinto".'],
  bites:[{ej:'Oyes la música de la tienda mientras juegas. Escuchas cuando un amigo te cuenta un problema y le pones cuidado.',check:{q:'Escuchar es…',o:['Poner atención para comprender','Solo percibir el sonido'],a:0,e:'Oír es del oído; escuchar es de la atención.'}},
   {ojo:'Si vas pensando tu respuesta mientras el otro habla, te pierdes la mitad de lo que dice.',check:{q:'¿Cuál es una señal de escucha activa?',o:['Asentir con la cabeza','Mirar el celular'],a:0,e:'Los gestos también muestran que pones atención.'}},
   {ej:'—Estoy nervioso por el examen de mañana. —O sea que te preocupa el examen, ¿cierto?',check:{q:'"O sea que te preocupa el examen" es…',o:['Parafrasear','Interrumpir'],a:0,e:'Repite con otras palabras lo que dijo el otro.'}},
   {ej:'"¡Buenas! ¿Cómo amaneció?" (saludar). "¿Y si le pago la mitad hoy?" (negociar). "Ojo, que el piso está mojado" (advertir). "Qué pena con usted" (disculparse). "Si quiere, le ayudo" (ofrecer).',check:{q:'"Vecino, el arroz de ayer tenía gorgojo" busca…',o:['Reclamar','Agradecer','Ofrecer'],a:0,e:'Señala un problema con lo que compró.'}},
   {ojo:'En Colombia "¿me regala…?" es una forma cortés de pedir; no significa que sea gratis.'},
   {ej:'—Buenos días, don Ernesto. ¿Me regala dos panes, por favor? —Con gusto, mija.',check:{q:'¿Cuál es una fórmula de cortesía?',o:['Con gusto','¡Muévase!'],a:0,e:'"Con gusto", "por favor" y "gracias" cuidan la relación.'}},
   {check:{q:'Ser asertivo es…',o:['Decir tu desacuerdo con respeto','Burlarte del que piensa distinto','Quedarte callado siempre'],a:0,e:'Asertivo: digo lo que pienso sin herir al otro.'}}],
  key:'Escucha activa: atención, preguntas y paráfrasis. Descubre la intención por las palabras y el tono. Responde con respeto y asertividad.',
  co:'La tienda de barrio es un gran escenario de diálogo: allí se pide fiado, se regatea, se comentan noticias y se usan fórmulas muy colombianas como "¿me regala…?" o "a la orden".',
  act:{type:'comic',prompt:'Completa la historieta: Camila escucha a don Ernesto y le responde con cortesía.',panels:[
   {who:'Camila',face:'🙂',say:'{{¡Buenos días, don Ernesto!|¡Quiubo, cucho!}} ¿Me regala una bolsa de leche, por favor?'},
   {who:'Don Ernesto',face:'🧓',say:'{{Qué pena con usted|Oiga, pues}}, mija, pero ya es la tercera vez que me paga con billete de cien mil. No me alcanza el cambio.'},
   {who:'Camila',face:'🤔',say:'{{O sea que necesita que le pague con billetes más pequeños|Ay, usted siempre se queja de todo}}, ¿cierto?'},
   {who:'Don Ernesto',face:'🙂',say:'Eso mismo. No estoy bravo: le estoy {{pidiendo|prohibiendo}} un favor.'},
   {who:'Camila',face:'😊',say:'{{Tiene razón, qué pena|Ese no es mi problema}}. Si quiere, hoy le pago con transferencia y la próxima vez le traigo billetes pequeños.'},
   {who:'Don Ernesto',face:'😄',say:'¡{{Con gusto|Ni modo}}, mija! {{Mil gracias|Allá usted}} por entender.'}],e:'Camila saluda, parafrasea, se disculpa y ofrece una solución: responde a lo que don Ernesto quiere.'},
  quiz:[{q:'¿Qué es parafrasear?',o:['Interrumpir para opinar','Repetir exactamente cada palabra','Decir con otras palabras lo que el otro dijo para comprobar que entendimos','Cambiar de tema'],a:2,e:'La paráfrasis muestra que escuchamos y evita malentendidos.',lv:'L'},
   {q:'Una clienta dice: "Vecino, el arroz que me vendió ayer tenía gorgojo". ¿Cuál es su intención?',o:['Agradecer','Reclamar','Ofrecer','Saludar'],a:1,e:'Señala un problema con lo que compró: es un reclamo.',lv:'I'},
   {q:'En un debate del salón, un compañero no deja hablar a nadie y se burla de las opiniones ajenas. ¿Qué principio del diálogo rompe?',o:['El de la brevedad','El respeto por los turnos y por el interlocutor','El uso de conectores','Ninguno: así se gana un debate'],a:1,e:'Dialogar exige escuchar y respetar al otro, aunque no se esté de acuerdo.',lv:'C'}],
  tip:'Haga parejas: uno cuenta algo durante un minuto y el otro solo puede parafrasear al final; luego cambian de papel. Después, pida que representen la historieta de la tienda en voz alta.'},
 {id:'g8u3l3',title:'El arte y su comunidad',time:50,std:'Relaciono manifestaciones artísticas no verbales con las personas y las comunidades humanas que las produjeron.',dba:'DBA 2 (8°): relaciona las manifestaciones artísticas con las comunidades y culturas en las que se producen.',
  body:['Un mural o un grafiti también es un <b>texto</b>: dice algo, alguien lo hizo y le habla a alguien. Para leerlo hacemos tres preguntas: <b>qué dice</b>, <b>quién</b> lo pintó y <b>a quién</b> se dirige.',
   'Los murales combinan palabras con <b>símbolos</b>: imágenes que representan ideas que la comunidad reconoce. Cada color y cada figura aporta un sentido.',
   'Algunos símbolos muy usados: la paloma blanca es la <b>paz</b>; las manos entrelazadas, la <b>solidaridad</b>; el puño en alto, la <b>lucha y la protesta</b>.',
   'En Colombia también se pintan frailejones (el <b>páramo, fábrica de agua</b>), colibríes, rostros indígenas y mariposas amarillas, un <b>guiño a García Márquez</b>.',
   'Otros símbolos hablan de la <b>identidad</b>. Los símbolos patrios son la bandera tricolor, el escudo y el himno nacional. El <b>cóndor</b> de los Andes, que está en el escudo, representa la libertad.',
   'La orquídea <i>Cattleya</i> es la flor nacional, y la palma de cera, el árbol nacional. El <b>sombrero vueltiao</b> es emblema del Caribe y de todo el país. La <b>mochila wayuu</b> es el tejido de las mujeres wayuu de La Guajira.',
   'El arte urbano nace de una <b>comunidad</b> y cuenta su memoria. En Bogotá están los murales de la calle 26 y el Distrito Grafiti de Puente Aranda; en Medellín, los grafitis de la <b>Comuna 13</b>. Leerlos es conocer a su gente.'],
  bites:[{ej:'Mural "La memoria también florece": qué dice → cuidemos el agua; quién → un colectivo del barrio; a quién → los jóvenes y quienes pasan en bus.',check:{q:'¿Cuáles son las tres preguntas para leer un mural?',o:['Qué dice, quién lo hizo y a quién le habla','Cuánto costó, cuánto mide y cuándo se seca'],a:0,e:'Son las mismas preguntas que le hacemos a cualquier texto.'}},
   {ojo:'Una paloma pintada en un mural no habla de aves: habla de paz. El símbolo está en lugar de una idea.',check:{q:'Un símbolo es…',o:['Una imagen que representa una idea','La firma del artista'],a:0,e:'La comunidad reconoce la idea detrás de la imagen.'}},
   {ej:'Un mural con una paloma blanca sobre las casas de un barrio habla de paz después de la violencia.',check:{q:'Unas manos entrelazadas representan…',o:['La solidaridad','La protesta'],a:0,e:'Manos unidas: apoyo entre las personas.'}},
   {ej:'Un mural con frailejones y gotas sobre una montaña invita a cuidar el páramo y el agua.'},
   {ojo:'Símbolos patrios: bandera, escudo e himno. Solo esos tres.',check:{q:'¿Qué representa el cóndor del escudo?',o:['La libertad','La paz'],a:0,e:'El cóndor de los Andes simboliza la libertad.'}},
   {ej:'En los partidos de la Selección, muchos hinchas llevan sombrero vueltiao.',check:{q:'La mochila wayuu es un tejido de…',o:['La Guajira','Nariño'],a:0,e:'La tejen las mujeres wayuu de La Guajira.'}},
   {ej:'Un turista y un vecino de la Comuna 13 leen distinto el mismo grafiti: el vecino conoce la historia del barrio.'}],
  key:'Un mural es un texto: qué dice, quién lo hizo, a quién le habla y qué símbolos usa (paloma: paz; manos: solidaridad; frailejón: agua; cóndor: libertad).',
  co:'Los murales de la calle 26 (avenida El Dorado) en Bogotá y los grafitis de la Comuna 13 de Medellín reciben cada año a miles de visitantes que recorren la ciudad leyendo sus paredes.',
  act:{type:'match',prompt:'Une cada símbolo con la idea que representa.',pairs:[['Paloma blanca','Paz'],['Manos entrelazadas','Solidaridad'],['Puño en alto','Lucha y protesta'],['Frailejón','Páramo, fábrica de agua'],['Cóndor de los Andes','Libertad'],['Mariposas amarillas','Guiño a García Márquez'],['Sombrero vueltiao','Emblema del Caribe'],['Mochila wayuu','Tejido de La Guajira']],e:'Un símbolo es una imagen que la comunidad reconoce como una idea.'},
  quiz:[{q:'¿Qué es un símbolo en un mural?',o:['Una imagen que representa una idea, como una paloma para la paz','La firma del artista','El tamaño de la pared','La pintura que sobra'],a:0,e:'El símbolo está en lugar de una idea que la comunidad reconoce.',lv:'L'},
   {q:'Un mural en un barrio muestra frailejones y gotas de agua sobre una montaña. ¿Qué mensaje probablemente transmite?',o:['Que hay que talar el páramo','Que el páramo produce agua y hay que cuidarlo','Que en el barrio venden plantas','Que va a llover'],a:1,e:'El frailejón se asocia con el páramo, fábrica de agua: el mural invita a protegerlo.',lv:'I'},
   {q:'¿Por qué un turista entiende distinto un grafiti de la Comuna 13 que alguien que vive allí?',o:['Porque el turista no ve bien','Porque el sentido de una obra depende de la historia y la memoria de la comunidad que la produjo','Porque los grafitis no tienen significado','Porque solo se entienden con guía pagado'],a:1,e:'La obra nace de una comunidad; conocer su contexto cambia la lectura.',lv:'C'}],
  tip:'Si es posible, recorra con el curso los murales cercanos al colegio; si no, proyecte fotos y pida que cada grupo "lea" uno con las tres preguntas.'}
]}
]};
export default grade;
